    P.txt('NOTICE OF CANCELLATION \u2014 ' + lab, 11, true); P.txt('Date of transaction: ____________   Seller: ' + DATA.seller, 10, true);
    DATA.ftc.concat(a.add).forEach(function(t){ P.txt(t, 10, true); }); P.txt(DATA.howto, 10, true); P.txt(DATA.busday, 9);
